    Object.defineProperty(p,"constructor",{get(){log+="g";Promise.resolve(2);return Promise;},configurable:true});
    const q=Promise.resolve(p);return log+(q===p);}

"use strict";async function run(){let log="";const p=Promise.resolve(7);
    Object.defineProperty(p,"constructor",{get(){log+="g";return Promise;},configurable:true});
    const value=await p;return log+value;}

"use strict";async function run(){let log="";const p=Promise.resolve(7);
    Object.defineProperty(p,"constructor",{get(){log+="g";return Promise;},configurable:true});
    const q=p.then(value=>value+1);return log+(await q);}

