    Object.defineProperty(p,"constructor",{get(){log+="g";throw 9;}});
    try{await p;}catch(error){log+=error;}finally{log+="f";}return log;}

"use strict";async function run(){let count=0;const p=Promise.resolve(7);
    Object.defineProperty(Promise.prototype,"constructor",{get(){count++;return Promise;},configurable:true});
    const value=await p;return count+value;}

"use strict";async function run(){let log='';const p=Promise.resolve(1);
    Object.defineProperty(p,'constructor',{get(){log+=this===p?'g':'bad';return Promise;}});
    async function h(){return p;}const q=h();queueMicrotask(()=>{log+='q';});await q;return log;}

"use strict";async function run(){let log='';const reason=Promise.resolve(9),p=Promise.resolve(1);
    function fail(){log+='h';throw reason;}
    Object.defineProperty(p,'constructor',{get(){log+='g';return fail();}});
    async function h(){return p;}const q=h();queueMicrotask(()=>{log+='q';});
    try{await q;}catch(error){log+=error===reason?'e':'bad';}finally{log+='f';}return log;}

"use strict";async function run(){let log='';const inner=Promise.resolve(2),p=Promise.resolve(1);
    Object.defineProperty(inner,'constructor',{get(){log+='i';return Promise;}});
    Object.defineProperty(p,'constructor',{get(){log+='o';Promise.resolve(inner);return undefined;}});
    async function h(){return p;}await h();return log;}

"use strict";async function run(){let log='',settle;const p=new Promise(resolve=>{settle=resolve;});
    Object.defineProperty(p,'constructor',{get(){log+='g';queueMicrotask(()=>{log+='s';settle(7);});return Promise;}});
    async function h(){return p;}const q=h();queueMicrotask(()=>{log+='q';});const value=await q;return log+value;}

"use strict";async function run(){let log='';const p=Promise.resolve(1);
    Object.defineProperty(p,'constructor',{configurable:true,get(){log+='g';Object.defineProperty(p,'constructor',{value:Promise});return Promise;}});
    async function h(){return p;}await h();return log+(Object.getOwnPropertyDescriptor(p,'constructor').value===Promise);}
